insert into public.item_options select * from jsonb_populate_recordset(null::public.item_options,'[{"id": "50a13920-e4fd-5701-b8fa-5a1a062c566f", "item_id": "02c6a864-0793-532f-b9f6-13c13e82b0be", "content_en": null, "content_hy": "Դրանք անընդհատ շարժվում են ամենատարբեր ուղղություններով, ուստի շարժումն անկանոն է։", "option_key": "A", "display_order": 1}, {"id": "f5dd694e-ffbd-534d-96d6-5caa8ffd4903", "item_id": "02c6a864-0793-532f-b9f6-13c13e82b0be", "content_en": null, "content_hy": "Դրանք շարժվում են միայն այն ժամանակ, երբ նյութն ամբողջությամբ տեղաշարժում են։", "option_key": "B", "display_order": 2}, {"id": "0c275ced-9baa-5228-a260-71625be7169d", "item_id": "02c6a864-0793-532f-b9f6-13c13e82b0be", "content_en": null, "content_hy": "Դրանք բոլորը շարժվում են նույն ուղղությամբ և ուղիղ գծերով։", "option_key": "C", "display_order": 3}, {"id": "2648b64a-0ad5-55e3-8056-6f17090d1098", "item_id": "02c6a864-0793-532f-b9f6-13c13e82b0be", "content_en": null, "content_hy": "Դրանք սովորական պայմաններում անշարժ են և միայն տաքացնելիս են սկսում շարժվել։", "option_key": "D", "display_order": 4}, {"id": "95d1b05d-e7f3-5bb6-93a7-85c261e9992c", "item_id": "e293a526-8a24-569b-9167-539373c1b1c5", "content_en": null, "content_hy": "A-ից B տանող մեկ ուղիղ հատված՝ առանց ուղղության փոփոխության։", "option_key": "A", "display_order": 1}, {"id": "9edd780b-4b5d-5021-a309-117bf3404cdc", "item_id": "e293a526-8a24-569b-9167-539373c1b1c5", "content_en": null, "content_hy": "Մոլեկուլը մնում է A կետում, մինչև ամբողջ գազը շարժվի դեպի B։", "option_key": "B", "display_order": 2}, {"id": "2a14e648-e9c1-54eb-bb59-5aa825ca8500", "item_id": "e293a526-8a24-569b-9167-539373c1b1c5", "content_en": null, "content_hy": "Տարբեր ուղղություններով բազմաթիվ կարճ հատվածներից կազմված բեկյալ ճանապարհ։", "option_key": "C", "display_order": 3}, {"id": "e04ed3f1-b5fb-575a-8079-d3448e70d676", "item_id": "e293a526-8a24-569b-9167-539373c1b1c5", "content_en": null, "content_hy": "Միևնույն շրջանագծով կրկնվող փակ ճանապարհ։", "option_key": "D", "display_order": 4}, {"id": "57c5681b-9b62-5bea-ad38-a313fcd99185", "item_id": "0fc5d1ef-4eff-5768-a293-be3a9c5b11ee", "content_en": null, "content_hy": "Բենզինի մոլեկուլները սկզբում անշարժ են և միայն մի քանի րոպե անց են սկսում շարժվել։", "option_key": "A", "display_order": 1}, {"id": "5a97b2fb-f42c-59d9-b396-0228db8ab607", "item_id": "0fc5d1ef-4eff-5768-a293-be3a9c5b11ee", "content_en": null, "content_hy": "Մոլեկուլի ակնթարթային արագությունն ամբողջությամբ նույնն է A-ից B հասնելու արագությանը, իսկ ուշացումն առաջանում է միայն մարդու հոտառությունից։", "option_key": "B", "display_order": 2}, {"id": "1029adc5-2bed-5066-9627-40229162b7dc", "item_id": "0fc5d1ef-4eff-5768-a293-be3a9c5b11ee", "content_en": null, "content_hy": "Բենզինի բոլոր մոլեկուլները սկզբում շարժվում են միայն ուղղահայաց վեր, ապա շրջվում են դեպի մարդը։", "option_key": "C", "display_order": 3}, {"id": "62d561c0-fbae-5ac8-88d8-bf4cfa502117", "item_id": "0fc5d1ef-4eff-5768-a293-be3a9c5b11ee", "content_en": null, "content_hy": "Օդի մոլեկուլների հետ բազմաթիվ բախումների պատճառով դրանց ուղղությունը շարունակ փոխվում է, և ուղիղ կարճ ճանապարհը դառնում է երկար բեկյալ ճանապարհ։", "option_key": "D", "display_order": 4}, {"id": "f66fa533-b359-5558-a0cd-32e2994c2de3", "item_id": "004a1306-59ed-5420-9642-4b89fc399800", "content_en": null, "content_hy": "Բախումից հետո այն կանգ է առնում և այլևս չի շարժվում։", "option_key": "A", "display_order": 1}, {"id": "9c9be1aa-2b5d-5f1d-88af-10ac93a5a55a", "item_id": "004a1306-59ed-5420-9642-4b89fc399800", "content_en": null, "content_hy": "Այն անկանոն բախվում է օդի մոլեկուլներին, և յուրաքանչյուր բախում կարող է փոխել շարժման ուղղությունը։", "option_key": "B", "display_order": 2}, {"id": "2f0e21fe-6e30-5091-9b50-ea658041b300", "item_id": "004a1306-59ed-5420-9642-4b89fc399800", "content_en": null, "content_hy": "Սենյակի օդը այն միշտ մղում է միայն մեկ հաստատուն ուղղությամբ։", "option_key": "C", "display_order": 3}, {"id": "003d5a3a-f052-57f1-a196-eed69e0b5a09", "item_id": "004a1306-59ed-5420-9642-4b89fc399800", "content_en": null, "content_hy": "Այն ընտրում է սենյակի մյուս կողմ հասնելու ամենակարճ ուղին։", "option_key": "D", "display_order": 4}]'::jsonb);
