insert into public.misconceptions select * from jsonb_populate_recordset(null::public.misconceptions,'[{"id": "cf67e740-57e3-53f9-8027-b69be98ba95f", "code": "particle_motion_requires_external_activation", "status": "active", "skill_id": "6a67089c-128a-55be-bfe0-3d2cd0524ad8", "title_hy": "Մասնիկների շարժումն արտաքին գործողությամբ սկսված համարելը", "created_at": "2026-10-01T16:37:11.896953+00:00", "updated_at": "2026-10-05T17:55:39.192203+00:00", "description_hy": "Սովորողը կարծում է, թե նյութի մասնիկներն անշարժ են և շարժվում են միայն ամբողջ մարմինը տեղաշարժելուց, տաքացնելուց կամ որոշ ժամանակ սպասելուց հետո։"}, {"id": "8d89ce97-498a-56b0-bc7a-3a8030e5f532", "code": "molecular_motion_ordered_or_predetermined", "status": "active", "skill_id": "6a67089c-128a-55be-bfe0-3d2cd0524ad8", "title_hy": "Մասնիկների շարժումը կարգավորված կամ նպատակաուղղված համարելը", "created_at": "2026-10-01T16:37:11.896953+00:00", "updated_at": "2026-10-05T17:55:14.15439+00:00", "description_hy": "Սովորողը մասնիկների անկանոն շարժումը փոխարինում է նույն ուղղությամբ, նախապես որոշված, շրջանաձև կամ նպատակակետ ընտրող շարժմամբ։"}, {"id": "f940d62a-b2d6-5aea-99fb-41111dcac923", "code": "collision_stops_molecular_motion", "status": "active", "skill_id": "6a67089c-128a-55be-bfe0-3d2cd0524ad8", "title_hy": "Բախումը մասնիկի շարժման ավարտ համարելը", "created_at": "2026-10-01T16:37:11.896953+00:00", "updated_at": "2026-10-05T17:54:45.328939+00:00", "description_hy": "Սովորողը կարծում է, թե այլ մոլեկուլի հետ բախվելուց հետո մասնիկը վերջնականապես կանգ է առնում՝ ուղղությունը փոխելու և շարժումը շարունակելու փոխարեն։"}, {"id": "0d64c75d-e084-5694-8c0e-bd1be6cf3d07", "code": "instantaneous_speed_equals_net_travel_speed", "status": "active", "skill_id": "6a67089c-128a-55be-bfe0-3d2cd0524ad8", "title_hy": "Ակնթարթային արագությունը ընդհանուր տեղաշարժի արագության հետ նույնացնելը", "created_at": "2026-10-01T16:37:11.896953+00:00", "updated_at": "2026-10-05T17:55:01.035952+00:00", "description_hy": "Սովորողը հաշվի չի առնում բազմաթիվ բախումներով երկար բեկյալ ճանապարհը և մասնիկի մեծ ակնթարթային արագությունը նույնացնում է երկու կետերի միջև արագ առաջխաղացման հետ։"}]'::jsonb);
