insert into public.item_template_remediation_guides select * from jsonb_populate_recordset(null::public.item_template_remediation_guides,'[{"id": "83845b83-f07e-5882-946c-d0f5b328e618", "status": "published", "metadata": {"sprint": "15B.6", "learnerVisible": false, "referenceMetadata": {"textbookSha256": "d8404d572f145d4afe924d0b8af900b3d9ed085a37893594667ab07a2ec12904", "textbookLocator": "Ֆիզիկա 7 (2023), Գլուխ II, §10, տպագիր էջեր 30-33, Խնդիր 3՝ էջ 40", "programmeOutcomeLocator": "7-րդ դասարան / Թեմա 2 / Վերջնարդյունքներ / Պարտադիր 1(3)"}}, "title_hy": "Ինչպե՞ս նկարագրել մասնիկների անկանոն շարժումը", "hint_1_hy": "Ստուգի՛ր երկու կարևոր հատկանիշ. շարժումը երբեք չի դադարում, իսկ շարժման ուղղությունները բազմազան են ու անկանոն։", "hint_2_hy": "Եթե մասնիկը բազմիցս բախվում է այլ մասնիկների, ուշադրությո՛ւն դարձրու ոչ թե միայն նրա արագությանը, այլև յուրաքանչյուր բախումից հետո տեղի ունեցող ուղղության փոփոխությանը։", "created_at": "2026-10-01T16:37:11.896953+00:00", "updated_at": "2026-10-05T14:13:17.830485+00:00", "strategy_hy": "Նախ հիշի՛ր, որ նյութի ատոմներն ու մոլեկուլներն անընդհատ գտնվում են շարժման մեջ։ Բախումները տեղի են ունենում անկանոն կերպով և կարող են փոխել յուրաքանչյուր մասնիկի շարժման ուղղությունը։ Այդ պատճառով երկար ժամանակամիջոցում մասնիկի անցած ճանապարհը բեկյալ գիծ է, այլ ոչ թե ուղիղ։ Մի նույնացրու մասնիկի մեծ ակնթարթային արագությունը երկու հեռավոր կետերի միջև նրա ընդհանուր արագության հետ։", "guide_version": 3, "item_template_id": "d82cc09f-9d5b-507c-886f-66e320558776", "worked_example_hy": "Օրինակ՝ բենզինի գոլորշու մոլեկուլը կարող է ունենալ մեծ արագություն, սակայն օդի մոլեկուլների հետ բազմակի բախումների հետևանքով դրա հետագիծը(A կետից B կետն ընկած ուղին) դառնում է բարդ բեկյալ գիծ, ուստի հոտն անմիջապես չի տարածվում ու հասնում մեզ։", "trigger_error_code": null, "allowed_parameter_keys": []}]'::jsonb);
insert into skill_outcomes select id,(select id from learning_outcomes limit 1) from skills;
